INSERT INTO bridging.notes
SELECT * FROM json_populate_recordset(null::bridging.notes, '[{"id":"019fa77d-8469-7104-aa43-56df5a5cb8fe","topic_id":"019f9df7-a2a0-71cf-9863-4d6d67e42e6d","subtopic_name":"Prime factorisation, HCF and LCM","summary":"Express numbers as products of primes in index form, then read HCF from shared primes at lowest powers and LCM from every prime at highest powers.","key_concepts":["A prime is greater than 1 and divisible only by itself and 1","HCF: common bases only, take the lowest power of each","LCM: every prime that appears, take the highest power of each","For a perfect square (cube), every prime power in the factorisation must be divisible by 2 (3)"],"formulas":[{"note":"Ignore primes that appear in only one number.","label":"HCF from primes","expression":"HCF = product of shared primes at lowest powers"},{"note":"Include primes found in only one of the numbers.","label":"LCM from primes","expression":"LCM = product of all primes at highest powers"}],"worked_examples":[{"steps":["560 = 2^4 x 5 x 7 and 168 = 2^3 x 3 x 7","Shared primes: 2 and 7","Lowest powers: 2^3 and 7","HCF = 2^3 x 7 = 56"],"answer":"56","question":"Find the HCF of 168 and 560."},{"steps":["2700 = 2^2 x 3^3 x 5^2","For a square, every power must be divisible by 2; only 3^3 needs one more factor of 3, so h = 3","For a cube, every power must be divisible by 3; need 2^1 and 5^1 more, so k = 2 x 5 = 10"],"answer":"2700 = 2^2 x 3^3 x 5^2; h = 3; k = 10","question":"Express 2700 as a product of primes. Find the smallest h so that 2700h is a perfect square, and the smallest k so that 2700k is a perfect cube."}],"common_mistakes":[{"fix":"HCF uses the lowest shared powers. Highest powers are for LCM.","mistake":"Taking the highest powers when finding the HCF."},{"fix":"LCM must include every prime that appears in either number.","mistake":"Leaving out a prime that appears in only one number when finding the LCM."}],"exam_tips":["Write both numbers in index form before comparing primes.","For square/cube questions, check which powers are not divisible by 2 or 3, then multiply by the missing factors."],"related_topic_codes":["t04"],"order_index":101,"level_band":null,"recommended_levels":null,"curriculum_stage":"O-Level","strand":null,"estimated_minutes":null,"revision_status":"published","created_at":"2026-07-28T06:50:48.807Z","updated_at":"2026-07-28T06:50:48.807Z"},{"id":"019fa77d-846f-77df-b73d-aeca15ab2712","topic_id":"019f9df7-a2a0-71cf-9863-4d6d67e42e6d","subtopic_name":"Indices and standard form","summary":"Index laws let you simplify powers without expanding. Standard form keeps very large or small numbers as A x 10^n with 1 <= A < 10.","key_concepts":["Same base: multiply by adding indices, divide by subtracting, and raise a power by multiplying indices","a^(-n) = 1/a^n and a^0 = 1 (a != 0)","Fractional indices are roots: a^(m/n) is the nth root of a^m","Standard form is A x 10^n where 1 <= A < 10"],"formulas":[{"note":"Bases must match for the first two laws.","label":"Core index laws","expression":"a^m x a^n = a^(m+n); a^m / a^n = a^(m-n); (a^m)^n = a^(mn)"},{"note":"Neither law applies when a = 0.","label":"Negative and zero index","expression":"a^(-n) = 1/a^n; a^0 = 1"},{"note":"Also (ab)^n = a^n b^n and (a/b)^m = a^m / b^m.","label":"Fractional index","expression":"a^(m/n) = (nth root of a)^m"}],"worked_examples":[{"steps":["Apply (ab)^n = a^n b^n and a^(m/n) as a root: (4x^2)^(3/2) = 4^(3/2) x (x^2)^(3/2)","4^(3/2) = (sqrt(4))^3 = 2^3 = 8","(x^2)^(3/2) = x^(2 x 3/2) = x^3"],"answer":"8x^3","question":"Simplify (4x^2)^(3/2)."},{"steps":["8^0 = 1","(1/2)^(-4) = (2/1)^4 = 16","16 x 1 = 16"],"answer":"16","question":"Evaluate (1/2)^(-4) x 8^0."}],"common_mistakes":[{"fix":"A negative index flips into a reciprocal; it does not change the sign.","mistake":"Treating a negative index as making the answer negative."},{"fix":"The first part must satisfy 1 <= A < 10, so write 3.4 x 10^6.","mistake":"Leaving standard form as 34 x 10^5."}],"exam_tips":["Rewrite nested roots and brackets fully in index form before simplifying from the inside out.","Spot zero powers early; they often collapse a messy expression to 1."],"related_topic_codes":["t04"],"order_index":102,"level_band":null,"recommended_levels":null,"curriculum_stage":"O-Level","strand":null,"estimated_minutes":null,"revision_status":"published","created_at":"2026-07-28T06:50:48.807Z","updated_at":"2026-07-28T06:50:48.807Z"},{"id":"019fa797-96d3-7fe3-9af0-0623a57032f0","topic_id":"019f9df7-a2a0-71cf-9863-4d6d67e42e6d","subtopic_name":"Significant figures, decimal places and estimation","summary":"Significant figures count from the first non-zero digit. Estimation checks whether an answer is a sensible size.","key_concepts":["Count significant figures from the first non-zero digit onwards","Leading zeros are never significant, but trailing zeros after a decimal point are","Decimal places are counted from the decimal point, regardless of zeros","Keep full accuracy through the working and round only at the final step"],"formulas":[{"note":"A quick way to confirm your exact answer is the right size.","label":"Estimation check","expression":"round each value to 1 significant figure, then calculate"}],"worked_examples":[{"steps":["0.0085: the leading zeros are not significant, so only the 8 and 5 count","20007: the zeros sit between non-zero digits, so all five digits count","12.000: trailing zeros after a decimal point are significant, so all five count"],"answer":"2, 5 and 5 significant figures","question":"State the number of significant figures in 0.0085, 20007 and 12.000."}],"common_mistakes":[{"fix":"Start counting at the first non-zero digit, giving 2 significant figures.","mistake":"Counting the leading zeros in 0.0085 as significant figures."},{"fix":"Trailing zeros after a decimal point show the accuracy and must be kept.","mistake":"Dropping the trailing zeros when writing 12.000."},{"fix":"Keep the full value in your calculator and round only the final answer.","mistake":"Rounding partway through a multi-step calculation."}],"exam_tips":["Check whether the question asks for significant figures or decimal places, they are not the same.","If the question does not specify, give money to 2 decimal places and other answers to 3 significant figures."],"related_topic_codes":["t04"],"order_index":103,"level_band":null,"recommended_levels":null,"curriculum_stage":"O-Level","strand":null,"estimated_minutes":null,"revision_status":"published","created_at":"2026-07-28T07:19:17.458Z","updated_at":"2026-07-28T07:19:17.458Z"},{"id":"019fa77d-846f-7886-a96c-1af51559f12c","topic_id":"019f9df7-a2a2-77cc-bb88-40ce254805a8","subtopic_name":"Ratio and proportional sharing","summary":"Ratios compare parts. Convert a ratio into total parts before sharing an amount.","key_concepts":["Ratios have no units and should be simplified","Total parts = sum of all ratio numbers","One part = total amount divided by total parts"],"formulas":[{"note":"Always find the value of one part first.","label":"Sharing in a ratio","expression":"share = (its part / total parts) x total amount"}],"worked_examples":[{"steps":["Let the numbers be x and 4x","After the change: (x - 5) and (4x + 10)","So (x - 5) / (4x + 10) = 1/6","6x - 30 = 4x + 10, so 2x = 40"],"answer":"20 yellow balls","question":"A bag has yellow and blue balls in the ratio 1:4. Five yellow are removed and 10 blue added, giving a new ratio 1:6. Find the original number of yellow balls."}],"common_mistakes":[{"fix":"A ratio only gives proportions. Find the value of one part first.","mistake":"Treating a ratio number as the actual quantity."},{"fix":"Convert both quantities to the same unit, then simplify.","mistake":"Forgetting to simplify units before writing a ratio."}],"exam_tips":["Set unknowns as x and 4x rather than two separate letters.","Check your answer satisfies the original ratio."],"related_topic_codes":["t06"],"order_index":201,"level_band":null,"recommended_levels":null,"curriculum_stage":"O-Level","strand":null,"estimated_minutes":null,"revision_status":"published","created_at":"2026-07-28T06:50:48.807Z","updated_at":"2026-07-28T06:50:48.807Z"},{"id":"019fa77d-846f-78a5-8c08-d120beccd3ac","topic_id":"019f9df7-a2a2-77cc-bb88-40ce254805a8","subtopic_name":"Direct and inverse proportion","summary":"Direct proportion means y = kx. Inverse proportion means y = k/x (or y = k over a power/root of x).","key_concepts":["Direct: as one quantity increases, the other increases and y = bx for a constant b","Inverse: as one quantity increases, the other decreases and y = b/x","Find the constant from the given pair first, then substitute the new value"],"formulas":[{"note":"b is the constant of proportionality.","label":"Direct proportion","expression":"y = bx"},{"note":"Also used with roots or powers, e.g. L = b / sqrt(M).","label":"Inverse proportion","expression":"y = b / x"}],"worked_examples":[{"steps":["y = bx so 144 = b(12), giving b = 12","When x = 7: y = 12 x 7 = 84"],"answer":"84","question":"y is directly proportional to x. Given y = 144 when x = 12, find y when x = 7."},{"steps":["L = b / sqrt(M)","35 = b / 10, so b = 350","700 = 350 / sqrt(M), so sqrt(M) = 1/2 and M = 1/4"],"answer":"M = 1/4","question":"L is inversely proportional to sqrt(M). When M = 100, L = 35. Find M when L = 700."}],"common_mistakes":[{"fix":"Always substitute the given pair to find b before answering.","mistake":"Skipping the step of finding the constant."},{"fix":"Inverse means y = b/x (or b over the stated expression).","mistake":"Using y = bx when the question says inversely proportional."}],"exam_tips":["Underline whether the question says directly or inversely proportional.","Label given and new values clearly so the constant step is easy to check."],"related_topic_codes":["t05"],"order_index":202,"level_band":null,"recommended_levels":null,"curriculum_stage":"O-Level","strand":null,"estimated_minutes":null,"revision_status":"published","created_at":"2026-07-28T06:50:48.807Z","updated_at":"2026-07-28T06:50:48.807Z"},{"id":"019fa797-96d4-7159-960a-e7b03b810be6","topic_id":"019f9df7-a2a2-77cc-bb88-40ce254805a8","subtopic_name":"Speed, distance and travel graphs","summary":"Speed links distance and time. On a travel graph the gradient gives speed and the area can give distance.","key_concepts":["Average speed uses total distance and total time, never the average of two speeds","On a distance-time graph the gradient is the speed","On a speed-time graph the area under the graph is the distance travelled","A horizontal line on a distance-time graph means the object is stationary"],"formulas":[{"note":"Rearranges to distance = speed x time.","label":"Speed","expression":"speed = distance / time"},{"note":"Never average the individual speeds.","label":"Average speed","expression":"average speed = total distance / total time"},{"note":"Multiply by 3.6 to convert m/s into km/h.","label":"Unit conversion","expression":"1 m/s = 3.6 km/h"}],"worked_examples":[{"steps":["First stage time = 60 / 40 = 1.5 hours","Second stage time = 60 / 60 = 1 hour","Total distance = 120 km and total time = 2.5 hours","Average speed = 120 / 2.5"],"answer":"48 km/h, not 50 km/h","question":"A car travels 60 km at 40 km/h, then a further 60 km at 60 km/h. Find the average speed for the whole journey."}],"common_mistakes":[{"fix":"Average speed is total distance over total time, which gives 48 km/h.","mistake":"Averaging the two speeds to get 50 km/h."},{"fix":"On a distance-time graph the speed is the gradient. The area has no meaning.","mistake":"Finding the area under a distance-time graph."},{"fix":"Convert to consistent units before substituting.","mistake":"Mixing units, such as distance in km with time in minutes."}],"exam_tips":["Write down what each axis shows before reading any travel graph.","For average speed, work out total distance and total time separately first."],"related_topic_codes":["t05"],"order_index":203,"level_band":null,"recommended_levels":null,"curriculum_stage":"O-Level","strand":null,"estimated_minutes":null,"revision_status":"published","created_at":"2026-07-28T07:19:17.458Z","updated_at":"2026-07-28T07:19:17.458Z"},{"id":"019fa797-96d4-7182-967a-27541bebc955","topic_id":"019f9df7-a2a2-77cc-bb88-40ce254805a8","subtopic_name":"Map scales and scale drawings","summary":"A map scale compares map length to actual length. Areas scale by the square of the length scale.","key_concepts":["Scale = D_map / D_actual, often rewritten as the representative fraction 1 : n","Both lengths must use the same unit before writing 1 : n","A_map / A_actual = (D_map / D_actual)^2"],"formulas":[{"note":"Reduce so the map side is 1.","label":"Length scale","expression":"scale = D_map / D_actual = 1 / n"},{"note":"Square the length scale factor.","label":"Area scale","expression":"A_map / A_actual = (D_map / D_actual)^2"}],"worked_examples":[{"steps":["1 cm represents 200000 cm = 2 km, so n = 2","Actual distance = 18.9 x 2 = 37.8 km","1 cm^2 represents 2^2 = 4 km^2, so map area = 728.6 / 4 = 182.15 cm^2"],"answer":"n = 2; 37.8 km; 182.15 cm^2","question":"A map has scale 1 : 200000. (a) Write as 1 cm : n km. (b) Map distance 18.9 cm. Find actual distance in km. (c) Actual area 728.6 km^2. Find map area in cm^2."}],"common_mistakes":[{"fix":"Square the length scale: areas scale by n^2.","mistake":"Using the length scale factor directly for an area."},{"fix":"Convert both lengths to the same unit before simplifying.","mistake":"Writing 1 : n with mixed units."}],"exam_tips":["Convert 1 : n into a convenient unit pair (e.g. 1 cm : 2 km) before area work.","Check whether the question asks for length or area; that decides whether you square."],"related_topic_codes":["t10"],"order_index":204,"level_band":null,"recommended_levels":null,"curriculum_stage":"O-Level","strand":null,"estimated_minutes":null,"revision_status":"published","created_at":"2026-07-28T07:19:17.458Z","updated_at":"2026-07-28T07:19:17.458Z"},{"id":"019fa77d-846f-78bf-9be6-38293f247790","topic_id":"019f9df7-a2a2-7839-8287-1e75e9dd37f8","subtopic_name":"Percentage change, profit and loss","summary":"Percentages are fractions with denominator 100. Most exam marks come from choosing the correct 100% baseline and using multipliers.","key_concepts":["Percent rate x base value = percentage amount","Increase uses (100% + rate); decrease uses (100% - rate)","Reverse percentage: final value is a known percent of the original, so divide by that multiplier"],"formulas":[{"note":"E.g. 8.5% of $7.20 is GST tax.","label":"Percentage of a base","expression":"amount = rate x base"},{"note":"Always measure against the previous (original) value.","label":"Percentage change","expression":"change / previous value x 100%"},{"note":"For reverse percentages, divide final by that multiplier.","label":"Increase / decrease multiplier","expression":"final = base x (100% +/- rate)"}],"worked_examples":[{"steps":["$17.50 is 85% of the original price","Original = 17.50 / 0.85 = 20.588...","Round to nearest cent"],"answer":"$20.59","question":"A pair of shoes costs $17.50 after a 15% discount. Find the price before discount."},{"steps":["Previous value = 1298 - 31 = 1267","Percentage increase = 31 / 1267 x 100% = 2.4467...%"],"answer":"2.45%","question":"An index rises from 1267 to 1298 (a change of +31). Find the percentage increase to 3 s.f."}],"common_mistakes":[{"fix":"Divide by 0.85. Reverse percentages divide by the remaining percent.","mistake":"Multiplying by 1.15 to reverse a 15% discount."},{"fix":"Percentage change is always measured against the previous value.","mistake":"Using the new value as the 100% baseline for percentage change."}],"exam_tips":["Write down what represents 100% before calculating.","On a calculator, key fraction x 100 (not x 100%) when converting to a percentage."],"related_topic_codes":["t01"],"order_index":301,"level_band":null,"recommended_levels":null,"curriculum_stage":"O-Level","strand":null,"estimated_minutes":null,"revision_status":"published","created_at":"2026-07-28T06:50:48.807Z","updated_at":"2026-07-28T06:50:48.807Z"},{"id":"019fa77d-846f-78da-8d36-a3c6c5093e2d","topic_id":"019f9df7-a2a2-7839-8287-1e75e9dd37f8","subtopic_name":"Simple and compound interest","summary":"Simple interest adds a fixed amount each period on the original principal. Compound interest recalculates on the new balance each period.","key_concepts":["Simple interest per period is constant and based on the original principal","Compound interest amount grows each period because interest is earned on the previous total","Compound formulas usually give the final amount A; interest earned is A - P"],"formulas":[{"note":"R is the rate as a decimal or percent/100; T is the number of periods.","label":"Simple interest","expression":"I = PRT; A = P(1 + RT)"},{"note":"A is the final amount after T compounding periods.","label":"Compound amount","expression":"A = P(1 + r/100)^T"}],"worked_examples":[{"steps":["I = 2300 x 0.03 x 2 = 138","A = 2300 + 138 = 2438 (or A = 2300(1 + 0.03 x 2))"],"answer":"Interest $138; amount $2438","question":"Deposit $2300 at 3% simple interest per year. Find the interest and amount after 2 years."},{"steps":["After 1 year: 12000 x 1.04 = 12480","After 2 years: 12000 x 1.04^2 = 12979.20"],"answer":"$12979.20","question":"Deposit $12000 at 4% compound interest per year. Find the amount after 2 years."}],"common_mistakes":[{"fix":"Interest earned = final amount minus the principal.","mistake":"Reporting the compound amount when the question asks for the interest."},{"fix":"Compound interest multiplies by (1 + r/100) once per period.","mistake":"Using simple interest when the question says compound."}],"exam_tips":["Check whether the question wants the total amount or just the interest.","For simple interest, A = P(1 + RT) is often faster than finding I first."],"related_topic_codes":["t02"],"order_index":302,"level_band":null,"recommended_levels":null,"curriculum_stage":"O-Level","strand":null,"estimated_minutes":null,"revision_status":"published","created_at":"2026-07-28T06:50:48.807Z","updated_at":"2026-07-28T06:50:48.807Z"},{"id":"019fa797-96d4-7391-a305-684acbf30080","topic_id":"019f9df7-a2a2-7839-8287-1e75e9dd37f8","subtopic_name":"Exchange rates, hire purchase and taxation","summary":"Convert currencies carefully with the given rate, and treat hire purchase as deposit plus all instalments (often with simple interest on the balance).","key_concepts":["Rewrite the exchange rate so the currency you want is on the RHS before multiplying","Hire purchase total = deposit + remaining amount + interest (if charged)","Tax is charged in bands, so only the income inside each band is taxed at that band''s rate"],"formulas":[{"note":"Invert the given rate if needed, then multiply.","label":"Currency conversion","expression":"new amount = original amount x (units of new per 1 unit of old)"},{"note":"Total payable = deposit + remaining amount + interest.","label":"Hire purchase instalment","expression":"instalment = (remaining amount + total interest) / number of instalments"}],"worked_examples":[{"steps":["1 EUR = 1/0.64 = 1.5625 SGD","30 EUR = 30 x 1.5625 = 46.875 SGD","Total = 46.875 + 7 = 53.875 SGD"],"answer":"53.88 SGD (2 d.p.)","question":"1 SGD = 0.64 EUR. A present costs 19 EUR + 11 EUR transport, plus 7 SGD import charges. Find the total in SGD."},{"steps":["Deposit = 0.4 x 50000 = 20000; remaining = 30000","Interest = 30000 x 0.025 = 750","Monthly instalment = (30000 + 750) / 24 = 1281.25","Total payable = 20000 + 30000 + 750 = 50750"],"answer":"$1281.25 per month; total $50750","question":"A car costs $50000. Deposit 40%, then 24 monthly instalments with 2.5% simple interest on the remaining amount. Find the monthly instalment and total payable."}],"common_mistakes":[{"fix":"Sanity-check the size, or rewrite the rate so the target currency is on the RHS.","mistake":"Multiplying when you should divide in a currency conversion."},{"fix":"Total = deposit + remaining balance + interest charged.","mistake":"Forgetting the deposit or the interest when totalling hire purchase."},{"fix":"Only the part of the income inside a band is taxed at that band''s rate.","mistake":"Taxing the whole income at the highest band rate."}],"exam_tips":["Write the exchange rate as a fraction and cancel units.","Hire purchase always costs at least as much as cash (usually more); use that as a check."],"related_topic_codes":["t01"],"order_index":303,"level_band":null,"recommended_levels":null,"curriculum_stage":"O-Level","strand":null,"estimated_minutes":null,"revision_status":"published","created_at":"2026-07-28T07:19:17.458Z","updated_at":"2026-07-28T07:19:17.458Z"},{"id":"019fa77e-4a20-77c9-9dbd-84e3b0a7ecaf","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","subtopic_name":"Expansion and factorisation","summary":"Expand by multiplying every term; factorise by extracting common factors or recognising identities. Only like terms can be combined.","key_concepts":["Only like terms can be added or subtracted (e.g. 2x + 3x = 5x)","Expand by multiplying the outside term (or each term) through every term in the bracket","Factorisation reverses expansion: take out the HCF, use identities, grouping, or the cross method"],"formulas":[{"note":"Spot these before using the general rainbow/FOIL method.","label":"Perfect square and difference of squares","expression":"(a + b)^2 = a^2 + 2ab + b^2; (a - b)^2 = a^2 - 2ab + b^2; a^2 - b^2 = (a + b)(a - b)"}],"worked_examples":[{"steps":["(3x + 5)^2 = 9x^2 + 2(3x)(5) + 25 = 9x^2 + 30x + 25","(x + 5)(x - 5) = x^2 - 25"],"answer":"9x^2 + 30x + 25; x^2 - 25","question":"Expand (3x + 5)^2 and (x + 5)(x - 5)."},{"steps":["49 - 4x^2 = 7^2 - (2x)^2 = (7 - 2x)(7 + 2x)","2a^2 - 8a = 2a(a - 4)"],"answer":"(7 - 2x)(7 + 2x); 2a(a - 4)","question":"Factorise completely 49 - 4x^2 and 2a^2 - 8a."}],"common_mistakes":[{"fix":"Include the middle term 2ab.","mistake":"Writing (a + b)^2 as a^2 + b^2."},{"fix":"Only like terms (same letters and powers) can be added or subtracted.","mistake":"Combining unlike terms such as 3x and 5."}],"exam_tips":["Expand your factorised answer mentally to check it.","Completely usually means take out a common factor and then factorise further."],"related_topic_codes":["t06"],"order_index":401,"level_band":null,"recommended_levels":null,"curriculum_stage":"O-Level","strand":null,"estimated_minutes":null,"revision_status":"published","created_at":"2026-07-28T06:51:39.424Z","updated_at":"2026-07-28T06:51:39.424Z"},{"id":"019fa77e-4a20-7a03-898c-3b69d3499409","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","subtopic_name":"Algebraic fractions and changing the subject","summary":"Combine algebraic fractions over a common denominator, and rearrange formulas so the required letter stands alone on the LHS.","key_concepts":["Factorise denominators before finding a common denominator; cancel factors only","Changing the subject means isolating one letter alone on the LHS","Square roots give +/- answers unless the context (e.g. distance) rejects the negative"],"formulas":[{"note":"Simplify the result if possible.","label":"Adding fractions","expression":"a/b + c/d = (ad + bc) / bd"}],"worked_examples":[{"steps":["Divide both sides by m: E/m = c^2","Square root both sides: c = +/- sqrt(E/m)"],"answer":"c = +/- sqrt(E/m)","question":"Make c the subject of E = mc^2."},{"steps":["Multiply both sides by 2: 2E = mv^2","Divide by v^2: m = 2E / v^2"],"answer":"m = 2E / v^2","question":"Make m the subject of E = (1/2)mv^2."}],"common_mistakes":[{"fix":"Only cancel a factor common to the whole numerator and denominator.","mistake":"Cancelling the x in (x + 3)/x."},{"fix":"Include both signs unless the question rejects negatives (e.g. length).","mistake":"Dropping the +/- when taking a square root in changing the subject."}],"exam_tips":["Undo operations in reverse order: clear fractions, isolate the powered term, then take roots.","When the new subject appears twice, collect those terms and factorise it out."],"related_topic_codes":["t06"],"order_index":402,"level_band":null,"recommended_levels":null,"curriculum_stage":"O-Level","strand":null,"estimated_minutes":null,"revision_status":"published","created_at":"2026-07-28T06:51:39.424Z","updated_at":"2026-07-28T06:51:39.424Z"},{"id":"019fa798-94cc-7fb5-ade9-4a1dcec6c8f9","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","subtopic_name":"Number patterns and the nth term","summary":"A linear sequence increases by the same amount each time, and its nth term takes the form an + b.","key_concepts":["The common difference is the amount added each time and becomes the coefficient of n","Check your nth term by substituting n = 1 to see if it gives the first term","The nth term lets you jump straight to any term without listing them all","A decreasing sequence has a negative common difference"],"formulas":[{"note":"a is the common difference and b adjusts the first term.","label":"Linear sequence","expression":"T_n = an + b"},{"note":"Because T_1 = a + b.","label":"Finding b","expression":"b = first term - a"}],"worked_examples":[{"steps":["The common difference is 3, so a = 3","b = first term - a = 5 - 3 = 2","So T_n = 3n + 2","T_20 = 3(20) + 2"],"answer":"T_n = 3n + 2 and the 20th term is 62","question":"Find the nth term of 5, 8, 11, 14, 17 and hence find the 20th term."}],"common_mistakes":[{"fix":"3n alone gives 3, 6, 9. The + 2 shifts it to 5, 8, 11.","mistake":"Writing the nth term as 3n when the sequence starts at 5."},{"fix":"Check the differences are all equal first. If they are not, an + b will not work.","mistake":"Assuming every sequence is linear."}],"exam_tips":["Always test your nth term with n = 1 and n = 2 before using it.","For a decreasing sequence a is negative, so expect a minus sign."],"related_topic_codes":["t06"],"order_index":403,"level_band":null,"recommended_levels":null,"curriculum_stage":"O-Level","strand":null,"estimated_minutes":null,"revision_status":"published","created_at":"2026-07-28T07:20:22.476Z","updated_at":"2026-07-28T07:20:22.476Z"},{"id":"019fa77e-4a20-7a3a-8806-6eebbef428fd","topic_id":"019f9df7-a2a2-7865-ab8c-df9bc214c173","subtopic_name":"Linear graphs and gradients","summary":"Every non-vertical straight line can be written as y = mx + c, where m is the gradient and c is the y-intercept.","key_concepts":["Gradient m = (y2 - y1) / (x2 - x1); a vertical line has undefined gradient","c is the value of y when x = 0","Parallel lines share the same gradient"],"formulas":[{"note":"Keep the order of subtraction consistent.","label":"Gradient from two points","expression":"m = (y2 - y1) / (x2 - x1)"},{"note":"If the line is vertical, write it as x = k.","label":"Equation of a line","expression":"y = mx + c"}],"worked_examples":[{"steps":["m = (-9 - (-5)) / (-1 - 3) = (-4) / (-4) = 1","Substitute (-1, -9): -9 = 1(-1) + c, so c = -8","Equation: y = x - 8"],"answer":"y = x - 8","question":"A is (3, -5) and B is (-1, -9). Find the equation of line AB."}],"common_mistakes":[{"fix":"Gradient is change in y over change in x.","mistake":"Computing gradient as change in x over change in y."},{"fix":"If you start with point 2 on top, start with point 2 on the bottom too.","mistake":"Mixing the order of points in numerator and denominator."}],"exam_tips":["Rearrange given equations into y = mx + c to read the gradient quickly.","Read the axis scales carefully before measuring a gradient off a graph."],"related_topic_codes":["t14"],"order_index":501,"level_band":null,"recommended_levels":null,"curriculum_stage":"O-Level","strand":null,"estimated_minutes":null,"revision_status":"published","created_at":"2026-07-28T06:51:39.424Z","updated_at":"2026-07-28T06:51:39.424Z"},{"id":"019fa77e-4a20-7a59-a2f1-9b582ffbba2f","topic_id":"019f9df7-a2a2-7865-ab8c-df9bc214c173","subtopic_name":"Quadratic and other graph shapes","summary":"Recognise graph shapes from equations. For quadratics, the line of symmetry passes through the turning point (minimum or maximum).","key_concepts":["a > 0 gives a U-shaped quadratic (minimum); a < 0 gives an n-shape (maximum)","Line of symmetry is midway between the roots; turning point lies on it","Completed-square form y = (x - h)^2 + k shows the turning point (h, k) directly","Other shapes: cubic, reciprocal y = a/x (axes as asymptotes), exponential y = a^x"],"formulas":[{"note":"Turning point is (h, k).","label":"Completed square form","expression":"y = (x - h)^2 + k"},{"note":"Does not meet the axes; a < 0 reflects into other quadrants.","label":"Reciprocal graph","expression":"y = a / x"}],"worked_examples":[{"steps":["Roots when y = 0: x = 5 or x = -1, so intercepts (5, 0) and (-1, 0)","Expand or put x = 0: y-intercept (0, 5)","x of turning point = (5 + (-1)) / 2 = 2; y = -(2 - 5)(2 + 1) = 9","Line of symmetry x = 2; maximum at (2, 9) since a < 0"],"answer":"Intercepts (5,0), (-1,0), (0,5); turning point (2,9); line x = 2","question":"For y = -(x - 5)(x + 1), find the x-intercepts, y-intercept, turning point and line of symmetry."},{"steps":["x^2 - 4x + 4 + 5 - 4 = (x - 2)^2 + 1","Minimum point (2, 1) because a > 0"],"answer":"(x - 2)^2 + 1","question":"Express x^2 - 4x + 5 in the form (x - h)^2 + k."}],"common_mistakes":[{"fix":"The x-coordinate is +2; the sign inside the bracket flips.","mistake":"Reading the turning point of (x - 2)^2 + 1 as (-2, 1)."},{"fix":"Draw a single smooth curve through the points.","mistake":"Joining plotted points with straight lines on a curve."}],"exam_tips":["Identify the shape from the equation before plotting.","Label axes and write the equation beside each sketch."],"related_topic_codes":["t06"],"order_index":502,"level_band":null,"recommended_levels":null,"curriculum_stage":"O-Level","strand":null,"estimated_minutes":null,"revision_status":"published","created_at":"2026-07-28T06:51:39.424Z","updated_at":"2026-07-28T06:51:39.424Z"},{"id":"019fa77e-4a20-7a72-9313-8026d7faa4f5","topic_id":"019f9df7-a2a2-7877-afdf-c436930f3059","subtopic_name":"Linear equations and inequalities","summary":"Solve inequalities like equations, but reverse the inequality sign when multiplying or dividing by a negative.","key_concepts":["Do the same operation to both sides","Adding/subtracting, or multiplying/dividing by a positive, keeps the inequality sign","Multiplying or dividing by a negative flips the inequality sign","On a number line: hollow circle for < or >; filled circle for <= or >="],"formulas":[{"note":"Dividing by -2 flips < to >.","label":"Sign reversal rule","expression":"If -2q < 10 then q > 5"}],"worked_examples":[{"steps":["Multiply both sides by 6: 3(2x + 1) >= 2(5 - 4x)","6x + 3 >= 10 - 8x","14x >= 7, so x >= 1/2"],"answer":"x >= 1/2","question":"Solve (2x + 1)/2 >= (5 - 4x)/3."},{"steps":["Multiply both sides by -4 and flip the sign","x <= -48"],"answer":"x <= -48","question":"Solve (-1/4)x >= 12."}],"common_mistakes":[{"fix":"Reverse the sign whenever you multiply or divide by a negative number.","mistake":"Keeping the inequality sign the same after dividing by a negative."},{"fix":"Hollow circle means excluded (< or >); filled means included (<= or >=).","mistake":"Using a filled circle for a strict inequality on a number line."}],"exam_tips":["After solving, test one value from your range to confirm it works.","Compound inequalities like 10 < x <= 20 mean both ends apply at once."],"related_topic_codes":["t04"],"order_index":601,"level_band":null,"recommended_levels":null,"curriculum_stage":"O-Level","strand":null,"estimated_minutes":null,"revision_status":"published","created_at":"2026-07-28T06:51:39.424Z","updated_at":"2026-07-28T06:51:39.424Z"},{"id":"019fa77e-4a20-7c37-92ed-92b483c805c2","topic_id":"019f9df7-a2a2-7877-afdf-c436930f3059","subtopic_name":"Simultaneous and quadratic equations","summary":"Two unknowns need two equations (elimination or substitution). Quadratics need factorising, the formula, or completing the square, and context may reject some roots.","key_concepts":["Elimination when coefficients can be matched; substitution when one variable is already isolated","A quadratic must be in the form ax^2 + bx + c = 0 before solving","In applications, reject roots that are impossible (e.g. negative rates or distances)"],"formulas":[{"note":"For ax^2 + bx + c = 0 with a != 0.","label":"Quadratic formula","expression":"x = (-b +/- sqrt(b^2 - 4ac)) / 2a"}],"worked_examples":[{"steps":["Multiply first equation by 3: 6x - 15y = -3","Subtract from second: (-4y) - (-15y) = 30 - (-3) => 11y = 33 => y = 3","Substitute: 2x - 15 = -1 => 2x = 14 => x = 7"],"answer":"x = 7, y = 3","question":"Solve 2x - 5y = -1 and 6x - 4y = 30 by elimination."},{"steps":["x = (30 +/- sqrt(900 + 60000)) / 6","x = 46.13 or x = -36.13","Reject the negative rate"],"answer":"x = 46.13 (reject -36.13)","question":"Solve 3x^2 - 30x - 5000 = 0 to 2 d.p. (pump rate; reject impossible roots)."}],"common_mistakes":[{"fix":"Move every term to one side so the equation reads ... = 0 first.","mistake":"Trying to factorise a quadratic that has not been rearranged to equal zero."},{"fix":"State both roots, then reject any that fail the context check.","mistake":"Giving only one solution to a quadratic."}],"exam_tips":["If answers are needed to 2 decimal places, use the quadratic formula.","Substitute both answers back into an original equation to check."],"related_topic_codes":["t05"],"order_index":602,"level_band":null,"recommended_levels":null,"curriculum_stage":"O-Level","strand":null,"estimated_minutes":null,"revision_status":"published","created_at":"2026-07-28T06:51:39.424Z","updated_at":"2026-07-28T06:51:39.424Z"},{"id":"019fa77f-0ed2-7580-a556-eae0ff73494a","topic_id":"019f9df7-a2a2-7888-aef2-fd58477eb864","subtopic_name":"Set notation and Venn diagrams","summary":"Sets group elements. Read the symbols carefully, then shade the matching region on a Venn diagram.","key_concepts":["Intersection (A intersect B) is elements in both; union (A union B) is elements in either","A'' is the complement: elements of the universal set not in A","A intersect B = empty set means the sets are disjoint (no overlap)","n(A) is the number of elements in A"],"formulas":[{"note":"Subtract the overlap so it is not counted twice.","label":"Union count","expression":"n(A union B) = n(A) + n(B) - n(A intersect B)"},{"note":"Universal set is often written as epsilon.","label":"Complement","expression":"A'' = universal set minus A"}],"worked_examples":[{"steps":["A intersect B = {4, 5}","B'' = {1,2,3,10}; A intersect B'' = {2,3}","(A intersect B'')'' is everything except {2,3}, i.e. {1,4,5,6,7,8,9,10}"],"answer":"A intersect B = {4,5}; shaded region is all except A-only","question":"With dummy sets epsilon = {1..10}, A = {2,3,4,5}, B = {4,5,6,7,8,9}, list A intersect B and describe (A intersect B'')''."}],"common_mistakes":[{"fix":"Elements in both sets would be counted twice. Subtract the intersection.","mistake":"Adding n(A) and n(B) without subtracting the overlap."},{"fix":"Union looks like a cup and collects everything; intersection is the overlap only.","mistake":"Confusing the union and intersection symbols."}],"exam_tips":["For shading questions, invent temporary dummy elements, shade, then erase them.","Fill the intersection of a Venn diagram first, then work outwards."],"related_topic_codes":["t17"],"order_index":701,"level_band":null,"recommended_levels":null,"curriculum_stage":"O-Level","strand":null,"estimated_minutes":null,"revision_status":"published","created_at":"2026-07-28T06:52:29.778Z","updated_at":"2026-07-28T06:52:29.778Z"},{"id":"019fa77f-0ed2-76b8-9b76-1055b754a2df","topic_id":"019f9df7-a2a2-7899-9f80-1aed5da88c11","subtopic_name":"Matrix operations and applications","summary":"Matrices store data in rows and columns. Addition needs matching order; multiplication needs the columns of the first to equal the rows of the second.","key_concepts":["Order is rows x columns; a square matrix has equal rows and columns","Add/subtract entry by entry only when orders match; scalar multiplies every entry","For AB, columns of A must equal rows of B; result has order (rows of A) x (columns of B)","AB is usually not the same as BA"],"formulas":[{"note":"Always state rows first.","label":"Order of a matrix","expression":"order = rows x columns"},{"note":"Inner numbers must match.","label":"Multiplication dimensions","expression":"(m x n) x (n x p) = (m x p)"}],"worked_examples":[{"steps":["(5 6 2 / 8 4 0) times (0.20 / 1.50 / 0.40)","Andy: 5(0.20)+6(1.50)+2(0.40) = 10.80","Mark: 8(0.20)+4(1.50)+0(0.40) = 7.60"],"answer":"(10.80 / 7.60); totals spent by Andy and Mark","question":"Andy buys 5 pencils, 6 pens, 2 erasers; Mark buys 8, 4, 0. Costs are $0.20, $1.50, $0.40. Form matrices and find each total spend."}],"common_mistakes":[{"fix":"Multiply each row of the first by each column of the second, then add.","mistake":"Multiplying matrices element by element."},{"fix":"Matrix multiplication is not commutative. Keep the given order.","mistake":"Assuming AB equals BA."}],"exam_tips":["Write the dimensions above each matrix before multiplying to check it is possible.","For interpretation questions, state what a row and a column represent in context."],"related_topic_codes":["t04"],"order_index":801,"level_band":null,"recommended_levels":null,"curriculum_stage":"O-Level","strand":null,"estimated_minutes":null,"revision_status":"published","created_at":"2026-07-28T06:52:29.778Z","updated_at":"2026-07-28T06:52:29.778Z"},{"id":"019fa77f-0ed2-76dd-afbc-7cc39778b1b2","topic_id":"019f9df7-a2a2-78ab-b1d6-52be9d287151","subtopic_name":"Angle properties in lines and triangles","summary":"Almost every angle question uses one of a small set of named rules, and you must quote the rule to get the reason mark.","key_concepts":["Angles on a straight line add to 180 degrees","Angles around a point add to 360 degrees","Vertically opposite angles are equal"],"formulas":[{"note":"True for every triangle.","label":"Angle sum of a triangle","expression":"a + b + c = 180 degrees"},{"note":"Saves a step in many problems.","label":"Exterior angle of a triangle","expression":"exterior = sum of the two opposite interior angles"}],"worked_examples":[{"steps":["Third interior angle = 180 - 47 - 68 = 65","Exterior angle = 180 - 65 = 115","Check: 47 + 68 = 115, matching the exterior angle rule"],"answer":"115 degrees","question":"In a triangle, two angles are 47 and 68 degrees. Find the exterior angle at the third vertex."}],"common_mistakes":[{"fix":"Name the rule, for example angles on a straight line, to earn the reason mark.","mistake":"Giving an answer with no reason stated."},{"fix":"Only use equal sides or angles that are marked or given.","mistake":"Assuming a triangle is isosceles because it looks like it."}],"exam_tips":["Mark every angle you calculate on the diagram as you go.","Diagrams are often not to scale, so never measure with a ruler."],"related_topic_codes":["t11"],"order_index":901,"level_band":null,"recommended_levels":null,"curriculum_stage":"O-Level","strand":null,"estimated_minutes":null,"revision_status":"published","created_at":"2026-07-28T06:52:29.778Z","updated_at":"2026-07-28T06:52:29.778Z"}]'::json)
ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.notes
SELECT * FROM json_populate_recordset(null::bridging.notes, '[{"id":"019fa77f-0ed2-76f7-97a7-9081e9270891","topic_id":"019f9df7-a2a2-78ab-b1d6-52be9d287151","subtopic_name":"Polygon angles","summary":"For any polygon, exterior angles always total 360 degrees. That single fact solves most polygon questions.","key_concepts":["Interior and exterior angles at a vertex add to 180 degrees","The exterior angles of any polygon sum to 360 degrees","In a regular polygon all exterior angles are equal"],"formulas":[{"note":"n is the number of sides.","label":"Interior angle sum","expression":"(n - 2) x 180 degrees"},{"note":"Rearranges to n = 360 / exterior angle.","label":"Regular polygon exterior angle","expression":"360 / n degrees"}],"worked_examples":[{"steps":["Let the angles be 5x and 4x","They sum to 180, so 9x = 180 and x = 20","Exterior angle = 4 x 20 = 80 degrees","n = 360 / 80 = 4.5, which is not a whole number"],"answer":"The number of sides is not an integer, so the polygon cannot exist.","question":"A regular polygon has interior to exterior angle ratio 5:4. Explain why this is impossible."}],"common_mistakes":[{"fix":"That formula gives the total. Divide by n for one angle of a regular polygon.","mistake":"Using (n - 2) x 180 as the size of one interior angle."},{"fix":"Sides must be a whole number. A fraction means the polygon is impossible.","mistake":"Accepting a non-integer number of sides."}],"exam_tips":["Work with exterior angles first, they are usually the faster route.","Check your final number of sides is a whole number of at least 3."],"related_topic_codes":["t13"],"order_index":902,"level_band":null,"recommended_levels":null,"curriculum_stage":"O-Level","strand":null,"estimated_minutes":null,"revision_status":"published","created_at":"2026-07-28T06:52:29.778Z","updated_at":"2026-07-28T06:52:29.778Z"},{"id":"019fa798-94cd-7100-a9bb-18e7f54d1f78","topic_id":"019f9df7-a2a2-78ab-b1d6-52be9d287151","subtopic_name":"Angles in parallel lines","summary":"When a line crosses two parallel lines, three named angle relationships appear again and again.","key_concepts":["Corresponding angles sit in matching positions and are equal, forming an F shape","Alternate angles sit on opposite sides of the transversal and are equal, forming a Z shape","Co-interior angles sit between the parallel lines on the same side and add to 180 degrees","These rules only apply when the lines are marked as parallel"],"formulas":[{"note":"F shape, in matching positions on the transversal.","label":"Corresponding angles","expression":"equal"},{"note":"Z shape, on opposite sides of the transversal.","label":"Alternate angles","expression":"equal"},{"note":"C shape, between the parallel lines on the same side.","label":"Co-interior angles","expression":"add to 180 degrees"}],"worked_examples":[{"steps":["Alternate angles are equal, so that angle is 68 degrees","Co-interior angles add to 180 degrees","180 - 68 = 112"],"answer":"Alternate angle 68 degrees, co-interior angle 112 degrees","question":"Two parallel lines are crossed by a transversal and one angle is 68 degrees. Find the alternate angle and the co-interior angle."}],"common_mistakes":[{"fix":"Corresponding angles form an F shape; alternate angles form a Z shape.","mistake":"Calling equal angles corresponding when they are actually alternate."},{"fix":"They add to 180 degrees, and are only equal when both are 90 degrees.","mistake":"Assuming co-interior angles are equal."},{"fix":"Look for the arrow markings. Without them these rules do not apply.","mistake":"Using parallel line rules when the lines are not marked parallel."}],"exam_tips":["Trace the F, Z and C shapes on the diagram to decide which rule applies.","Name the rule in your answer, the reason usually carries its own mark."],"related_topic_codes":["t11"],"order_index":903,"level_band":null,"recommended_levels":null,"curriculum_stage":"O-Level","strand":null,"estimated_minutes":null,"revision_status":"published","created_at":"2026-07-28T07:20:22.476Z","updated_at":"2026-07-28T07:20:22.476Z"},{"id":"019fa798-94cd-7126-b8a2-f1c4cb68dab4","topic_id":"019f9df7-a2a2-78ab-b1d6-52be9d287151","subtopic_name":"Properties of quadrilaterals","summary":"Each special quadrilateral has its own set of side, angle and diagonal properties, and naming questions turn on the diagonals.","key_concepts":["A square has four equal sides, four right angles, and diagonals that are equal and bisect at right angles","A rectangle has equal diagonals that bisect each other, but not at right angles","A rhombus has four equal sides and diagonals that bisect at right angles but are unequal","A parallelogram has opposite sides equal and parallel and opposite angles equal","A kite has two pairs of adjacent equal sides, and one diagonal bisects the other at right angles"],"formulas":[{"note":"True for every quadrilateral.","label":"Angle sum of a quadrilateral","expression":"a + b + c + d = 360 degrees"},{"note":"a and b are the parallel sides, h the perpendicular height between them.","label":"Trapezium area","expression":"area = 1/2 (a + b) h"}],"worked_examples":[{"steps":["Diagonals crossing at right angles rules out the rectangle and the plain parallelogram","Equal diagonals would make it a square, but here they are unequal","The remaining shape with these properties is a rhombus"],"answer":"A rhombus","question":"A quadrilateral has diagonals that bisect each other at right angles but are not equal in length. Name it and justify your answer."}],"common_mistakes":[{"fix":"A rhombus has diagonals that bisect at right angles but are different lengths. Equal diagonals means a square or rectangle.","mistake":"Saying a rhombus has equal diagonals."},{"fix":"Only use properties that are marked or stated in the question.","mistake":"Assuming a shape is a square because it looks like one."},{"fix":"Compare them on three checks: equal sides, right angles, and what the diagonals do.","mistake":"Mixing up rhombus, rectangle and parallelogram properties."}],"exam_tips":["Build a table of the six quadrilaterals against sides, angles and diagonals, and learn it.","For naming questions, quote the property that rules out the other shapes."],"related_topic_codes":["t13"],"order_index":904,"level_band":null,"recommended_levels":null,"curriculum_stage":"O-Level","strand":null,"estimated_minutes":null,"revision_status":"published","created_at":"2026-07-28T07:20:22.476Z","updated_at":"2026-07-28T07:20:22.476Z"},{"id":"019fa798-94cd-7323-b7a3-4c838289aef8","topic_id":"019f9df7-a2a2-78ab-b1d6-52be9d287151","subtopic_name":"Perpendicular and angle bisector constructions","summary":"Two ruler-and-compass constructions come up regularly: the perpendicular bisector of a line and the bisector of an angle.","key_concepts":["Every point on a perpendicular bisector is the same distance from both end points","Every point on an angle bisector is the same distance from both arms of the angle","Construction arcs must be left visible because they show the method","Set the compass to more than half the line length so the arcs actually cross"],"formulas":[{"note":"Cuts the line in half at 90 degrees.","label":"Perpendicular bisector","expression":"equal arcs from both end points, then join the crossing points"},{"note":"Splits the angle into two equal halves.","label":"Angle bisector","expression":"one arc across both arms, then equal arcs from those two points"}],"worked_examples":[{"steps":["Open the compass to more than half of AB","Draw arcs above and below the line from A, then repeat from B with the same radius","Join the two points where the pairs of arcs cross"],"answer":"The line drawn is the perpendicular bisector of AB, which is the required locus","question":"Describe how to construct the locus of points equidistant from two points A and B."}],"common_mistakes":[{"fix":"The arcs show your method and carry marks. Leave them on the page.","mistake":"Rubbing out the construction arcs to tidy up the diagram."},{"fix":"Keep the same radius for each pair of arcs.","mistake":"Changing the compass width partway through a construction."},{"fix":"Construct means ruler and compasses only.","mistake":"Measuring with a protractor when the question says construct."}],"exam_tips":["Use a sharp pencil and draw the arcs long enough to cross clearly.","Equidistant from two points means perpendicular bisector; equidistant from two lines means angle bisector."],"related_topic_codes":["t14"],"order_index":905,"level_band":null,"recommended_levels":null,"curriculum_stage":"O-Level","strand":null,"estimated_minutes":null,"revision_status":"published","created_at":"2026-07-28T07:20:22.476Z","updated_at":"2026-07-28T07:20:22.476Z"},{"id":"019fa77f-0ed2-7889-a1bc-441d9ff8f55c","topic_id":"019f9df7-a2a2-78c7-aa4b-565799c65ce4","subtopic_name":"Congruence and similarity","summary":"Congruent triangles are the same shape and size. Similar triangles have the same shape with corresponding sides in proportion.","key_concepts":["Congruence tests: SSS, SAS, ASA, AAS, RHS (state the test used)","Similarity tests: AAA (two equal angles suffice), SSS sides proportional, SAS sides proportional with included equal angle","Congruent figures are identical in shape and size; similar figures share shape but not necessarily size"],"formulas":[{"note":"Match corresponding sides carefully.","label":"Length scale factor","expression":"k = corresponding length on larger / corresponding length on smaller"},{"note":"Square or cube the length factor for similar figures.","label":"Area and volume scaling","expression":"area ratio = k^2; volume ratio = k^3"}],"worked_examples":[{"steps":["Two corresponding sides equal with the included angle equal","This is SAS congruence"],"answer":"SAS","question":"State which congruence rule applies when two triangles have two equal sides and the included equal angle."},{"steps":["Length scale factor k = 10 / 4 = 2.5","Volume scale factor = k^3 = 15.625","Larger volume = 32 x 15.625 = 500"],"answer":"500 cm^3","question":"Two similar solids have heights 4 cm and 10 cm. The smaller has volume 32 cm^3. Find the volume of the larger."}],"common_mistakes":[{"fix":"AAA proves similarity, not congruence; sizes may differ.","mistake":"Claiming congruence from AAA alone."},{"fix":"Square it for area and cube it for volume.","mistake":"Using the length scale factor directly for area or volume."}],"exam_tips":["Sketch both triangles the same way round before pairing sides.","In proofs, name the triangles in corresponding vertex order and state the test (e.g. SAS)."],"related_topic_codes":["t13"],"order_index":1001,"level_band":null,"recommended_levels":null,"curriculum_stage":"O-Level","strand":null,"estimated_minutes":null,"revision_status":"published","created_at":"2026-07-28T06:52:29.778Z","updated_at":"2026-07-28T06:52:29.778Z"},{"id":"019fa77f-0ed2-78b5-bca6-3887a60c34d2","topic_id":"019f9df7-a2a2-78da-b367-27466579928e","subtopic_name":"Circle properties and theorems","summary":"A short list of circle theorems covers nearly every question. Identify which one the diagram is showing before calculating.","key_concepts":["The angle in a semicircle is a right angle","A tangent meets a radius at 90 degrees","Angles in the same segment are equal"],"formulas":[{"note":"Both must stand on the same arc.","label":"Angle at the centre","expression":"angle at centre = 2 x angle at circumference"},{"note":"All four vertices must lie on the circle.","label":"Cyclic quadrilateral","expression":"opposite angles add to 180 degrees"}],"worked_examples":[{"steps":["Angle ACB = 90 degrees, angle in a semicircle","Angles in triangle ABC sum to 180","Angle ABC = 180 - 90 - 34"],"answer":"56 degrees","question":"A, B and C lie on a circle with AB a diameter. Angle BAC is 34 degrees. Find angle ABC."}],"common_mistakes":[{"fix":"The centre angle is the larger one. It is double the circumference angle.","mistake":"Halving the wrong angle in the centre and circumference theorem."},{"fix":"Check all four vertices lie on the circumference first.","mistake":"Applying the cyclic quadrilateral rule when a vertex is not on the circle."}],"exam_tips":["Look for the diameter first, it usually signals a right angle.","Name the theorem you used, the reason often carries its own mark."],"related_topic_codes":["t09"],"order_index":1101,"level_band":null,"recommended_levels":null,"curriculum_stage":"O-Level","strand":null,"estimated_minutes":null,"revision_status":"published","created_at":"2026-07-28T06:52:29.778Z","updated_at":"2026-07-28T06:52:29.778Z"},{"id":"019fa780-0e84-7e60-b2fc-65a592509a11","topic_id":"019f9df7-a2a2-78eb-97ed-a2f26cb15634","subtopic_name":"Pythagoras and right-angled trigonometry","summary":"In a right-angled triangle, use Pythagoras for three sides and SOHCAHTOA when an angle is involved.","key_concepts":["Hypotenuse is the longest side, opposite the right angle","Label opposite, adjacent and hypotenuse relative to the angle you are using","Use inverse sin/cos/tan to find an angle from two sides"],"formulas":[{"note":"c is the hypotenuse.","label":"Pythagoras theorem","expression":"a^2 + b^2 = c^2"},{"note":"Choose the ratio that uses the two sides you know.","label":"SOHCAHTOA","expression":"sin = O/H; cos = A/H; tan = O/A"}],"worked_examples":[{"steps":["Known opposite and hypotenuse, so use sine","sin theta = 3/5 = 0.6","theta = inverse sin(0.6)"],"answer":"theta = 36.9 degrees (1 d.p.)","question":"In a right-angled triangle, opposite = 3, adjacent = 4, hypotenuse = 5. Find the angle theta opposite the side of length 3."}],"common_mistakes":[{"fix":"Pythagoras only relates three sides. Use trigonometry when an angle appears.","mistake":"Using Pythagoras when one of the given values is an angle."},{"fix":"Set the calculator to degrees before any trigonometry.","mistake":"Leaving the calculator in radian mode."}],"exam_tips":["Label O, A and H relative to your chosen angle before picking a ratio.","Check the hypotenuse is the longest side in your answer."],"related_topic_codes":["t13"],"order_index":1201,"level_band":null,"recommended_levels":null,"curriculum_stage":"O-Level","strand":null,"estimated_minutes":null,"revision_status":"published","created_at":"2026-07-28T06:53:35.236Z","updated_at":"2026-07-28T06:53:35.236Z"},{"id":"019fa780-0e85-70c4-877c-8f32e666862f","topic_id":"019f9df7-a2a2-78eb-97ed-a2f26cb15634","subtopic_name":"Sine rule, cosine rule and bearings","summary":"For triangles without a right angle, choose the sine rule or cosine rule based on what you are given.","key_concepts":["Sine rule needs a matching side and opposite angle pair","Cosine rule is for two sides and the included angle, or all three sides","Bearings are measured clockwise from north as three digits"],"formulas":[{"note":"Use when you have a side and its opposite angle.","label":"Sine rule","expression":"a / sin A = b / sin B = c / sin C"},{"note":"A is the angle between sides b and c.","label":"Cosine rule","expression":"a^2 = b^2 + c^2 - 2bc cos A"},{"note":"C is the angle between sides a and b.","label":"Area of a triangle","expression":"area = 1/2 ab sin C"}],"worked_examples":[{"steps":["Two sides and the included angle, so use the cosine rule","a^2 = 49 + 81 - 2(7)(9)cos 62","a^2 = 130 - 126 x 0.4695 = 70.85","a = square root of 70.85"],"answer":"a = 8.42 cm to 3 significant figures","question":"In triangle ABC, b = 7 cm, c = 9 cm and angle A = 62 degrees. Find a."}],"common_mistakes":[{"fix":"That case needs the cosine rule, because no side and opposite angle pair is complete.","mistake":"Using the sine rule when you only know two sides and the angle between them."},{"fix":"Bearings use three digits, so write 045 degrees.","mistake":"Writing a bearing as 45 degrees."}],"exam_tips":["Check what you are given before choosing a rule, it decides the method.","For bearings, draw a north arrow at every point mentioned."],"related_topic_codes":["t15"],"order_index":1202,"level_band":null,"recommended_levels":null,"curriculum_stage":"O-Level","strand":null,"estimated_minutes":null,"revision_status":"published","created_at":"2026-07-28T06:53:35.236Z","updated_at":"2026-07-28T06:53:35.236Z"},{"id":"019fa799-85b9-76bf-98d8-05beca89012f","topic_id":"019f9df7-a2a2-78eb-97ed-a2f26cb15634","subtopic_name":"Angles of elevation, depression and 3D problems","summary":"Elevation and depression turn real situations into right-angled triangles. In three dimensions, work one triangle at a time.","key_concepts":["An angle of elevation is measured up from the horizontal and an angle of depression is measured down from it","The angle of elevation from A to B equals the angle of depression from B to A, because the horizontals are parallel","In a 3D problem, pick out one right-angled triangle at a time and redraw it flat","You often need Pythagoras on the base before using trigonometry on a vertical triangle"],"formulas":[{"note":"They are alternate angles between two parallel horizontal lines.","label":"Elevation and depression","expression":"angle of elevation = angle of depression"},{"note":"Find this first, then use it as the base of the vertical triangle.","label":"Base diagonal of a cuboid","expression":"d = sqrt(l^2 + w^2)"}],"worked_examples":[{"steps":["The angle of depression from the cliff equals the angle of elevation at the boat, so the triangle has a 25 degree angle at the boat","The 40 m cliff is opposite that angle and the distance d is adjacent","tan 25 = 40 / d","d = 40 / tan 25 = 40 / 0.4663"],"answer":"85.8 m to 3 significant figures","question":"From the top of a 40 m cliff the angle of depression of a boat is 25 degrees. Find the distance of the boat from the foot of the cliff."}],"common_mistakes":[{"fix":"Both elevation and depression are measured from the horizontal.","mistake":"Measuring the angle of depression from the vertical."},{"fix":"Transfer it to the bottom of the triangle as an equal angle of elevation, which is usually simpler.","mistake":"Using the depression angle directly as the angle inside the triangle at the top."},{"fix":"Redraw each right-angled triangle separately and flat before calculating.","mistake":"Trying to solve a 3D problem on the original solid."}],"exam_tips":["Sketch the horizontal dashed line first, then mark the elevation or depression angle from it.","In 3D questions, name the triangle you are working in before substituting."],"related_topic_codes":["t13"],"order_index":1203,"level_band":null,"recommended_levels":null,"curriculum_stage":"O-Level","strand":null,"estimated_minutes":null,"revision_status":"published","created_at":"2026-07-28T07:21:24.153Z","updated_at":"2026-07-28T07:21:24.153Z"},{"id":"019fa780-0e85-70f7-afe0-beb56ca779e6","topic_id":"019f9df7-a2a2-78fc-bd9e-a40e9b4f9363","subtopic_name":"Area, perimeter and circles","summary":"Break composite shapes into simple ones, and keep track of which parts of the perimeter are actually included.","key_concepts":["Perimeter is a length, area is a squared unit","An arc is a fraction of the circumference given by its angle","Composite shapes are best split into rectangles, triangles and circle parts"],"formulas":[{"note":"Check whether you are given the radius or the diameter.","label":"Circle","expression":"circumference = 2 pi r, area = pi r^2"},{"note":"x is the angle at the centre in degrees.","label":"Arc length and sector area","expression":"arc = (x / 360) x 2 pi r, sector = (x / 360) x pi r^2"}],"worked_examples":[{"steps":["Radius = 7 cm","Curved part = half of 2 pi x 7 = 7 pi = 21.99 cm","Add the straight diameter: 21.99 + 14"],"answer":"35.99 cm, about 36.0 cm","question":"Find the perimeter of a semicircle of diameter 14 cm."}],"common_mistakes":[{"fix":"The perimeter is the curved arc plus the diameter.","mistake":"Forgetting the straight edge when finding a semicircle perimeter."},{"fix":"Halve the diameter before substituting into the formula.","mistake":"Using the diameter in place of the radius."}],"exam_tips":["Write the units on every answer, cm for perimeter and cm^2 for area.","Keep pi in your calculator rather than using 3.14 until the final step."],"related_topic_codes":["t10"],"order_index":1301,"level_band":null,"recommended_levels":null,"curriculum_stage":"O-Level","strand":null,"estimated_minutes":null,"revision_status":"published","created_at":"2026-07-28T06:53:35.236Z","updated_at":"2026-07-28T06:53:35.236Z"},{"id":"019fa780-0e85-7115-8248-b56954b32be6","topic_id":"019f9df7-a2a2-78fc-bd9e-a40e9b4f9363","subtopic_name":"Volume and surface area of solids","summary":"Volume fills a solid, surface area covers it. Curved surface area is the part most often forgotten.","key_concepts":["Prism volume is always cross-sectional area times length","Cones and pyramids include a factor of one third","Total surface area means every face, including the base if it is closed"],"formulas":[{"note":"Add two circles for a closed cylinder.","label":"Cylinder","expression":"volume = pi r^2 h, curved surface = 2 pi r h"},{"note":"l is the slant height, found with Pythagoras.","label":"Cone","expression":"volume = 1/3 pi r^2 h, curved surface = pi r l"},{"note":"A hemisphere is half the volume plus a flat circle.","label":"Sphere","expression":"volume = 4/3 pi r^3, surface area = 4 pi r^2"}],"worked_examples":[{"steps":["Volume = 1/3 pi r^2 h","= 1/3 x pi x 9 x 8","= 24 pi"],"answer":"75.4 cm^3 to 3 significant figures","question":"Find the volume of a cone of radius 3 cm and vertical height 8 cm."}],"common_mistakes":[{"fix":"Volume uses the vertical height. Slant height is only for curved surface area.","mistake":"Using the slant height in the cone volume formula."},{"fix":"Any solid that tapers to a point needs the one third factor.","mistake":"Omitting the one third for cones and pyramids."}],"exam_tips":["Decide whether the solid is open or closed before totalling surface area.","Volume answers use cubic units, surface area uses squared units."],"related_topic_codes":["t12"],"order_index":1302,"level_band":null,"recommended_levels":null,"curriculum_stage":"O-Level","strand":null,"estimated_minutes":null,"revision_status":"published","created_at":"2026-07-28T06:53:35.236Z","updated_at":"2026-07-28T06:53:35.236Z"},{"id":"019fa780-0e85-712d-a090-4b3d82b18a9b","topic_id":"019f9df7-a2a2-790d-b90f-3e453f40cd4c","subtopic_name":"Coordinate geometry","summary":"The Cartesian plane uses perpendicular x- and y-axes meeting at the origin (0, 0). Points, midpoints and distances are the basic tools.","key_concepts":["A point is written (x, y); the origin is (0, 0)","Read scales carefully: each small square may represent 1 unit or a fraction of a unit","Distance between two points comes from Pythagoras on the coordinate differences","Midpoint is the average of the x-coordinates and of the y-coordinates"],"formulas":[{"note":"Average each coordinate separately.","label":"Midpoint","expression":"((x1 + x2)/2, (y1 + y2)/2)"},{"note":"Same as length of the line segment joining the points.","label":"Distance","expression":"sqrt((x2 - x1)^2 + (y2 - y1)^2)"}],"worked_examples":[{"steps":["Left of the origin means negative x","Above the origin means positive y"],"answer":"(-4, 7)","question":"A point is 4 units left of the origin and 7 units above it. State its coordinates."},{"steps":["y difference = -9 - (-5) = -4; x difference = -1 - 3 = -4","Distance = sqrt((-4)^2 + (-4)^2) = sqrt(32) = 5.66 units (3 s.f.)"],"answer":"5.66 units (3 s.f.)","question":"Find the distance between A(3, -5) and B(-1, -9)."}],"common_mistakes":[{"fix":"Midpoint means average: add and divide by two.","mistake":"Subtracting coordinates when finding a midpoint."},{"fix":"Check what each small square represents before reading coordinates.","mistake":"Misreading the grid scale when plotting or reading a point."}],"exam_tips":["Always label the x-axis and y-axis on sketches.","Plot points roughly to sanity-check distance and midpoint answers."],"related_topic_codes":["t05"],"order_index":1401,"level_band":null,"recommended_levels":null,"curriculum_stage":"O-Level","strand":null,"estimated_minutes":null,"revision_status":"published","created_at":"2026-07-28T06:53:35.236Z","updated_at":"2026-07-28T06:53:35.236Z"},{"id":"019fa780-0e85-714b-8123-58667f21b215","topic_id":"019f9df7-a2a2-791f-bec6-372d238905de","subtopic_name":"Vectors in two dimensions","summary":"A vector has magnitude and direction. Add by the triangle/parallelogram law, and use column vectors for components.","key_concepts":["Vector AB means go from A to B; BA = -AB","Triangle law: AB + BC = AC; subtract by adding the negative","Parallel vectors are scalar multiples; collinear points have AB = k AC","Magnitude of column vector (x / y) is sqrt(x^2 + y^2)"],"formulas":[{"note":"For the column vector (x / y).","label":"Magnitude","expression":"|v| = sqrt(x^2 + y^2)"},{"note":"Destination minus start.","label":"Displacement","expression":"AB = position of B - position of A"}],"worked_examples":[{"steps":["|BA| = sqrt(8^2 + (-6)^2) = 10","Position of A - BA = position of B: (-9 / 2) - (8 / -6) = (-17 / 8), so B = (-17, 8)","(m / -3) = k(8 / -6); k = (-3)/(-6) = 1/2, so m = 4"],"answer":"|BA| = 10; B = (-17, 8); m = 4","question":"A is (-9, 2) and BA = (8 / -6). Find |BA|, the coordinates of B, and m if CD = (m / -3) is parallel to BA."}],"common_mistakes":[{"fix":"AB = b - a (end minus start).","mistake":"Writing AB as a - b when OA = a and OB = b."},{"fix":"Add the components first, then apply the magnitude formula.","mistake":"Adding magnitudes to get the magnitude of a sum."}],"exam_tips":["Draw arrows on the diagram for every vector you write down.","If two vectors are parallel, write one as k times the other and solve for k."],"related_topic_codes":["t12"],"order_index":1501,"level_band":null,"recommended_levels":null,"curriculum_stage":"O-Level","strand":null,"estimated_minutes":null,"revision_status":"published","created_at":"2026-07-28T06:53:35.236Z","updated_at":"2026-07-28T06:53:35.236Z"},{"id":"019fa780-0e85-71ab-b016-3c60cee766c0","topic_id":"019f9df7-a2a2-7930-a717-cd252273c91f","subtopic_name":"Averages and measures of spread","summary":"Mean, median and mode summarise a data set differently. Range is the simplest measure of spread for ungrouped data.","key_concepts":["Mean = sum of observations / number of observations","Mode is the most frequent value","Median is the middle value after ordering; for an even count, average the two middle values","Range = largest value - smallest value"],"formulas":[{"note":"N is the number of observations.","label":"Mean (ungrouped)","expression":"mean = (sum of x) / N"},{"note":"For even N, average the values at N/2 and N/2 + 1.","label":"Median position (odd N)","expression":"position = (N + 1) / 2"}],"worked_examples":[{"steps":["Order: 1, 2, 3, 5, 9","N = 5 (odd), so position = (5 + 1) / 2 = 3","Median is the 3rd value"],"answer":"3","question":"Find the median of 9, 5, 3, 1, 2."},{"steps":["Already ordered; N = 6","Middle positions 3 and 4: values 8 and 10","Median = (8 + 10) / 2 = 9"],"answer":"9","question":"Find the median of 2, 4, 8, 10, 12, 15."}],"common_mistakes":[{"fix":"Always sort into ascending order first.","mistake":"Finding the median without ordering the data."},{"fix":"The mode is the value that appears most often.","mistake":"Calling every common value a mode without checking frequency."}],"exam_tips":["State whether you used mean, median or mode, and give units when relevant.","If outliers matter, the median is usually more representative than the mean."],"related_topic_codes":["t17"],"order_index":1601,"level_band":null,"recommended_levels":null,"curriculum_stage":"O-Level","strand":null,"estimated_minutes":null,"revision_status":"published","created_at":"2026-07-28T06:53:35.236Z","updated_at":"2026-07-28T06:53:35.236Z"},{"id":"019fa799-85bc-7e0f-b6c8-3e8869a04a9e","topic_id":"019f9df7-a2a2-7930-a717-cd252273c91f","subtopic_name":"Standard deviation and comparing data sets","summary":"Standard deviation measures spread about the mean. Use mean and SD together to compare two data sets in context.","key_concepts":["Larger SD means values are more spread out / less consistent","For grouped data, use class mid-points with frequencies","Compare average (mean) and spread (SD) separately, using the question context"],"formulas":[{"note":"Equivalent to sqrt(mean of squares - square of mean).","label":"SD (ungrouped)","expression":"s.d. = sqrt( sum((x - mean)^2) / N )"},{"note":"x is the mid-point of each class. Write ''standard deviation'' in full in answers.","label":"Mean and SD (grouped)","expression":"mean = sum(fx)/sum(f); s.d. = sqrt( sum(f x^2)/sum(f) - (mean)^2 )"}],"worked_examples":[{"steps":["Mean = 23/5 = 4.6","Sum of (x - mean)^2 = 53.2","s.d. = sqrt(53.2 / 5) = 3.26 (3 s.f.)"],"answer":"3.26 (3 s.f.)","question":"Find the standard deviation of 5, 0, 9, 7, 2."},{"steps":["sum(f) = 82; mean = sum(fx)/82 ≈ 71.5","s.d. = sqrt( mean of squares - square of mean ) ≈ 12.2 (3 s.f.)"],"answer":"Mean about 71.5; standard deviation 12.2 (3 s.f.)","question":"Grouped marks with mid-points 55,65,75,85,95 and frequencies 15,28,18,13,8. Find mean and SD."}],"common_mistakes":[{"fix":"It is mean of the squares minus the square of the mean (never negative).","mistake":"Subtracting in the wrong order inside the square root."},{"fix":"Mention both the average and the spread for full marks.","mistake":"Comparing two data sets using the mean alone."}],"exam_tips":["Set out a table of mid-point x, f, fx and f x^2 before substituting.","A smaller standard deviation means more consistent results in context."],"related_topic_codes":["t17"],"order_index":1602,"level_band":null,"recommended_levels":null,"curriculum_stage":"O-Level","strand":null,"estimated_minutes":null,"revision_status":"published","created_at":"2026-07-28T07:21:24.153Z","updated_at":"2026-07-28T07:21:24.153Z"},{"id":"019fa799-85bc-7e8f-847b-a45e098e814a","topic_id":"019f9df7-a2a2-7930-a717-cd252273c91f","subtopic_name":"Statistical diagrams and cumulative frequency curves","summary":"Frequency tables and diagrams organise data. A cumulative frequency curve gives median and quartiles by reading across and down.","key_concepts":["Grouped frequency tables use class intervals; read inequality signs carefully when tallying","A cumulative frequency curve plots running total against the upper class boundary","Median at n/2; lower quartile at n/4; upper quartile at 3n/4 on the vertical axis"],"formulas":[{"note":"n is the total frequency.","label":"Median position on CF curve","expression":"read across at n / 2"},{"note":"IQR = UQ - LQ.","label":"Quartile positions","expression":"LQ at n/4; UQ at 3n/4"}],"worked_examples":[{"steps":["For the median, read across from 100 on the CF axis to the curve, then down to the marks axis","For scores above 70, read up from 70 to find how many scored 70 or less","Number above 70 = 200 minus that reading"],"answer":"Median at CF = 100; number above 70 = 200 - CF reading at 70","question":"A cumulative frequency curve covers 200 students. Explain how to find the median and how many scored more than 70."}],"common_mistakes":[{"fix":"Read at half the total frequency on the vertical (CF) axis.","mistake":"Reading the median halfway along the marks axis."},{"fix":"Plot against the upper class boundary.","mistake":"Plotting cumulative frequency against the class midpoint."},{"fix":"Check whether the interval uses < or <= before tallying.","mistake":"Misreading class inequalities when building a frequency table."}],"exam_tips":["Draw reading lines onto the graph to show your method.","Check the curve finishes at the total frequency."],"related_topic_codes":["t17"],"order_index":1603,"level_band":null,"recommended_levels":null,"curriculum_stage":"O-Level","strand":null,"estimated_minutes":null,"revision_status":"published","created_at":"2026-07-28T07:21:24.153Z","updated_at":"2026-07-28T07:21:24.153Z"},{"id":"019fa780-0e85-71c2-9e50-7ca09aa18fbc","topic_id":"019f9df7-a2a2-7941-9e48-3d4dda1f252c","subtopic_name":"Probability of single and combined events","summary":"Probability is a fraction between 0 and 1. Tree diagrams and tables keep combined events organised.","key_concepts":["All probabilities of an event and its complement add to 1","Multiply along the branches of a tree diagram, add between branches","Without replacement changes the denominator for the second pick"],"formulas":[{"note":"Assumes all outcomes are equally likely.","label":"Single event","expression":"P(event) = favourable outcomes / total outcomes"},{"note":"Often much faster than counting directly.","label":"Complement","expression":"P(not A) = 1 - P(A)"},{"note":"Only when one does not affect the other.","label":"Independent events","expression":"P(A and B) = P(A) x P(B)"}],"worked_examples":[{"steps":["First counter red: 5/8","Now 4 red out of 7 remain, so second red: 4/7","Multiply along the branches: 5/8 x 4/7 = 20/56"],"answer":"5/14","question":"A bag has 5 red and 3 blue counters. Two are taken without replacement. Find the probability both are red."}],"common_mistakes":[{"fix":"The total drops by one, and so does the count of that colour.","mistake":"Keeping the same denominator for the second pick without replacement."},{"fix":"Multiply along a branch. Only add between separate branches.","mistake":"Adding probabilities along a tree branch."}],"exam_tips":["Look for the phrase at least, it usually means use 1 minus the opposite.","Check every set of branch probabilities adds to 1."],"related_topic_codes":["t07"],"order_index":1701,"level_band":null,"recommended_levels":null,"curriculum_stage":"O-Level","strand":null,"estimated_minutes":null,"revision_status":"published","created_at":"2026-07-28T06:53:35.236Z","updated_at":"2026-07-28T06:53:35.236Z"}]'::json)
