INSERT INTO bridging.questions
SELECT * FROM json_populate_recordset(null::bridging.questions, '[{"id":"019f9e72-b6b2-762e-982d-9a230904d542","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","prompt":"Write x^2 - 10x + 7 in the form (x - a)^2 + b.","model_answer":"(x - 5)^2 - 18","explanation":"Complete the square: x^2 - 10x + 7 = (x^2 - 10x + 25) - 25 + 7 = (x - 5)^2 - 18.","difficulty":"Easy","metadata":{"tags":"algebra,quadratics,completing-the-square","subtopic":"completing the square","question_type":"open-ended","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-07-26T12:42:25.842Z","updated_at":"2026-07-26T12:42:25.842Z"},{"id":"019f9e72-b681-7ab4-b97f-c92fe8c20252","topic_id":"019f9df7-a2a2-77cc-bb88-40ce254805a8","prompt":"A shirt costs £14.75 in one country. In another country, the same shirt costs $21.99. If the exchange rate is $1 = £0.73, calculate how much more the second price is than the first, in pounds.","model_answer":"£1.30","explanation":"Convert $21.99 to pounds: 21.99 × 0.73 = 16.0527. Subtract 14.75: 16.0527 - 14.75 = 1.3027. To the nearest penny, the difference is £1.30.","difficulty":"Easy","metadata":{"tags":"ratio,exchange-rates,money","subtopic":"exchange rates","question_type":"open-ended","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-07-26T12:42:25.793Z","updated_at":"2026-07-26T12:42:25.793Z"},{"id":"019f9e72-b688-7ff9-971b-1d6c0e1ef6df","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","prompt":"Simplify 6a^5b^2 ÷ 3a^2b.","model_answer":"2a^3b","explanation":"Divide coefficients: 6 ÷ 3 = 2. Subtract the powers: a^(5-2) = a^3 and b^(2-1) = b. So the simplified form is 2a^3b.","difficulty":"Easy","metadata":{"tags":"algebra,indices,simplification","subtopic":"indices","question_type":"open-ended","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-07-26T12:42:25.800Z","updated_at":"2026-07-26T12:42:25.800Z"},{"id":"019f9e72-b68b-7f17-b8a8-f777ff35747f","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","prompt":"Use the laws of indices to find the value of k if 2^k × 2^4 = 64.","model_answer":"2","explanation":"Combine the powers: 2^(k+4) = 64. Since 64 = 2^6, we get k + 4 = 6. Therefore k = 2.","difficulty":"Easy","metadata":{"tags":"algebra,indices,laws-of-indices","subtopic":"indices","question_type":"open-ended","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-07-26T12:42:25.803Z","updated_at":"2026-07-26T12:42:25.803Z"},{"id":"019f9e72-b68e-79f7-923d-49cece0f994c","topic_id":"019f9df7-a2a0-71cf-9863-4d6d67e42e6d","prompt":"A number p has exactly 12 factors. Two of its factors are 4 and 15. Find one possible value of p.","model_answer":"60","explanation":"The number must be divisible by both 4 and 15, so it must be a multiple of 60. Now 60 = 2^2 × 3 × 5, so the number of factors is (2+1)(1+1)(1+1) = 12. Therefore one possible value is 60.","difficulty":"Medium","metadata":{"tags":"numbers,factors,prime-factorisation","subtopic":"factors","question_type":"open-ended","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-07-26T12:42:25.806Z","updated_at":"2026-07-26T12:42:25.806Z"},{"id":"019f9e72-b691-7764-8288-e89f71e5bb84","topic_id":"019f9df7-a2a0-71cf-9863-4d6d67e42e6d","prompt":"Express 840 as a product of prime factors.","model_answer":"2^3 × 3 × 5 × 7","explanation":"840 = 84 × 10 = (2^2 × 3 × 7) × (2 × 5) = 2^3 × 3 × 5 × 7.","difficulty":"Easy","metadata":{"tags":"numbers,prime-factorisation","subtopic":"prime factorisation","question_type":"open-ended","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-07-26T12:42:25.809Z","updated_at":"2026-07-26T12:42:25.809Z"},{"id":"019f9e72-b69b-7385-b3c7-64e19ae59966","topic_id":"019f9df7-a2a0-71cf-9863-4d6d67e42e6d","prompt":"The least common multiple of 12, x and 28 is 420. Find two possible values of x between 12 and 100.","model_answer":"15 and 35","explanation":"420 = 2^2 × 3 × 5 × 7. Since 12 = 2^2 × 3 and 28 = 2^2 × 7, x must contribute a factor of 5 without creating higher powers that change the LCM. Two possible values are 15 and 35.","difficulty":"Medium","metadata":{"tags":"numbers,lcm,factors","subtopic":"lcm","question_type":"open-ended","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-07-26T12:42:25.819Z","updated_at":"2026-07-26T12:42:25.819Z"},{"id":"019f9e72-b69e-73de-893e-74388ffc703e","topic_id":"019f9df7-a2a2-7839-8287-1e75e9dd37f8","prompt":"Jessica invests $4540 at a rate of r% per year compound interest. At the end of 10 years, she has earned $1328.54 in interest. Find the value of r.","model_answer":"2.5%","explanation":"Final amount = 4540 + 1328.54 = 5868.54. So 4540(1 + r/100)^10 = 5868.54. Divide by 4540 to get (1 + r/100)^10 = 1.292. Taking the 10th root gives 1 + r/100 ≈ 1.025. Therefore r = 2.5%.","difficulty":"Medium","metadata":{"tags":"percentages,compound-interest,finance","subtopic":"compound interest","question_type":"open-ended","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-07-26T12:42:25.822Z","updated_at":"2026-07-26T12:42:25.822Z"},{"id":"019f9e72-b6af-777a-893b-e66b9f69cf0e","topic_id":"019f9df7-a2a2-78ab-b1d6-52be9d287151","prompt":"A regular polygon has interior angle to exterior angle ratio 5:4. Explain why this is impossible.","model_answer":"The number of sides is not a whole number.","explanation":"Let the interior angle be 5x and the exterior angle be 4x. Since they add up to 180°, 9x = 180, so x = 20 and the exterior angle is 80°. The number of sides would be 360 ÷ 80 = 4.5, which is not an integer, so such a regular polygon is impossible.","difficulty":"Medium","metadata":{"tags":"angles,polygons,reasoning","subtopic":"polygons","question_type":"open-ended","diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-07-26T12:42:25.839Z","updated_at":"2026-07-26T12:42:25.839Z"},{"id":"01a00459-8bb0-79e6-ade9-c46eddf891d7","topic_id":"019f9df7-a2a2-7888-aef2-fd58477eb864","prompt":"A cumulative frequency graph for 160 students shows the lower quartile at 56 marks and the upper quartile at 72 marks. Find the interquartile range.","model_answer":"16","explanation":"Interquartile range = upper quartile - lower quartile = 72 - 56 = 16.","difficulty":"Easy","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:36:12.464Z","updated_at":"2026-08-15T07:36:12.464Z"},{"id":"01a00459-8bb6-77a0-8cd3-3690d5b4530c","topic_id":"019f9df7-a2a0-71cf-9863-4d6d67e42e6d","prompt":"Write as a single fraction in its simplest form: 3/(x + 2) + 1/(x - 2).","model_answer":"(4x - 4)/(x^2 - 4)","explanation":"The common denominator is (x + 2)(x - 2) = x^2 - 4. The numerator becomes 3(x - 2) + (x + 2) = 4x - 4. So the single fraction is (4x - 4)/(x^2 - 4).","difficulty":"Medium","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:36:12.470Z","updated_at":"2026-08-15T07:36:12.470Z"},{"id":"01a00459-8bc7-7e97-891d-72fad8fdb80e","topic_id":"019f9df7-a2a0-71cf-9863-4d6d67e42e6d","prompt":"Expand and simplify (2x - 5)(x + 4).","model_answer":"2x^2 + 3x - 20","explanation":"Multiply each term: 2x(x + 4) - 5(x + 4) = 2x^2 + 8x - 5x - 20 = 2x^2 + 3x - 20.","difficulty":"Easy","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:36:12.487Z","updated_at":"2026-08-15T07:36:12.487Z"},{"id":"01a00459-8bcc-7c1a-af1d-41720b9197b5","topic_id":"019f9df7-a2a0-71cf-9863-4d6d67e42e6d","prompt":"Factorise completely: 6y^2 - 15y.","model_answer":"3y(2y - 5)","explanation":"Take out the common factor 3y. This gives 6y^2 - 15y = 3y(2y - 5).","difficulty":"Easy","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:36:12.492Z","updated_at":"2026-08-15T07:36:12.492Z"},{"id":"01a00459-8bdc-7410-ba31-9a3cb9aea481","topic_id":"019f9df7-a2a0-71cf-9863-4d6d67e42e6d","prompt":"Factorise completely: x^2 - 9x + 20.","model_answer":"(x - 4)(x - 5)","explanation":"Find two numbers whose product is 20 and sum is -9. They are -4 and -5, so the expression factorises to (x - 4)(x - 5).","difficulty":"Easy","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:36:12.508Z","updated_at":"2026-08-15T07:36:12.508Z"},{"id":"01a00459-8bef-7ab5-a104-7e114d0dc45f","topic_id":"019f9df7-a2a2-7839-8287-1e75e9dd37f8","prompt":"y is directly proportional to the cube root of (x + 1). It is given that x = 7 when y = 1. Find the value of y when x = 124.","model_answer":"2.5","explanation":"Let y = k∛(x + 1). When x = 7, 1 = k∛8 = 2k, so k = 1/2. When x = 124, y = 1/2 × ∛125 = 1/2 × 5 = 2.5.","difficulty":"Medium","metadata":{"diagram_required":false},"diagram_path":null,"question_type":null,"answer_tolerance":null,"accepted_answers":null,"case_sensitive":null,"require_simplified_form":null,"require_units":null,"required_unit":null,"accepted_units":null,"marking_notes":null,"syntax_migration_status":null,"syntax_migration_notes":null,"created_at":"2026-08-15T07:36:12.527Z","updated_at":"2026-08-15T07:36:12.527Z"}]'::json)
